NEW_FILES = {'.github/workflows/brand-sync.yml': 'name: Brand sync\n\n# RNV-COLOUR-SYNC, 2026-10-16 (#38 B). Once a day, read rnv-brand\'s head and\n# write this application\'s colours from it with tools/sync_colors.py.\n#\n#   No colour this app uses moved  -> nothing is opened. The run ends there.\n#   One did                        -> the tests run on the change, and ONE pull\n#                                     request is opened with the new pin,\n#                                     ui/colors.py and COLORS.md. If it is\n#                                     still open the next day, it is updated,\n#                                     not opened again.\n#\n# Merge it, and the next build carries the new colours. Nothing reads the\n# brand while the application runs.\n#\n# Needs one repository setting: Settings > Actions > General > Workflow\n# permissions > "Allow GitHub Actions to create and approve pull requests".\n# rnv-brand is public, so no token beyond the workflow\'s own.\n#\n# A pull request opened by this workflow\'s token does not start the other\n# workflows, which is GitHub\'s rule for that token. So this job runs the two\n# suites itself and says in the pull request whether they were green.\n\non:\n  schedule:\n    - cron: "17 6 * * *"\n  workflow_dispatch:\n\npermissions:\n  contents: write\n  pull-requests: write\n\nconcurrency:\n  group: brand-sync\n  cancel-in-progress: false\n\njobs:\n  sync:\n    name: Sync colours from rnv-brand / Python 3.13\n    runs-on: ubuntu-latest\n    timeout-minutes: 30\n\n    steps:\n      - name: Check out repository\n        uses: actions/checkout@v5\n\n      - name: Set up Python 3.13\n        uses: actions/setup-python@v6\n        with:\n          python-version: "3.13"\n\n      # The sync reads the colour file as the application does, so the\n      # application\'s own packages, and Qt\'s system libraries, come first.\n      - name: Install system Qt dependencies\n        run: |\n          sudo apt-get update\n          sudo apt-get install -y --no-install-recommends \\\n            libegl1 \\\n            libxkbcommon0 \\\n            libxkbcommon-x11-0 \\\n            libdbus-1-3 \\\n            libxcb-cursor0 \\\n            libxcb-icccm4 \\\n            libxcb-image0 \\\n            libxcb-keysyms1 \\\n            libxcb-randr0 \\\n            libxcb-render-util0 \\\n            libxcb-shape0 \\\n            libxcb-xinerama0 \\\n            libxcb-xkb1 \\\n            libfontconfig1\n\n      - name: Pin the brand\'s head and write the colours from it\n        id: sync\n        env:\n          QT_QPA_PLATFORM: offscreen\n        run: |\n          # A sync that refuses -- the brand dropped a name this app uses -- fails\n          # the run, so it is seen, rather than passing as "nothing moved".\n          set -o pipefail\n          head=$(git ls-remote https://github.com/RNVizion/rnv-brand HEAD | cut -f1)\n          echo "head=$head" >> "$GITHUB_OUTPUT"\n          sed -i -E "s#(rnv-brand @ git\\+https://github\\.com/RNVizion/rnv-brand(\\.git)?@)[0-9a-f]{40}#\\1$head#" tests/requirements-dev.txt\n          python -m pip install --upgrade pip\n          pip install -r requirements.txt -r tests/requirements-dev.txt\n          if ! python -c "import engine.brand"; then\n            echo "::warning::rnv-brand at ${head:0:7} does not import; nothing was synced."\n            echo "moved=no" >> "$GITHUB_OUTPUT"\n            exit 0\n          fi\n          python tools/sync_colors.py | tee sync.log\n          if git diff --quiet -- ui/colors.py; then\n            echo "No colour this app uses moved at rnv-brand ${head:0:7}. Nothing to open."\n            echo "moved=no" >> "$GITHUB_OUTPUT"\n          else\n            echo "moved=yes" >> "$GITHUB_OUTPUT"\n          fi\n\n      - name: Run the tests on the change\n        if: steps.sync.outputs.moved == \'yes\'\n        id: tests\n        env:\n          QT_QPA_PLATFORM: offscreen\n        run: |\n          if { python run_tests.py; } > tests.log 2>&1; then\n            echo "result=green" >> "$GITHUB_OUTPUT"\n          else\n            echo "result=red" >> "$GITHUB_OUTPUT"\n          fi\n          tail -n 40 tests.log\n\n      - name: Open the pull request, or update the one already open\n        if: steps.sync.outputs.moved == \'yes\'\n        env:\n          GH_TOKEN: ${{ github.token }}\n          HEAD: ${{ steps.sync.outputs.head }}\n          RESULT: ${{ steps.tests.outputs.result }}\n        run: |\n          git config user.name "github-actions[bot]"\n          git config user.email "41898282+github-actions[bot]@users.noreply.github.com"\n          git switch -C brand-sync\n          git add tests/requirements-dev.txt ui/colors.py COLORS.md\n          git commit -m "Brand sync: rnv-brand@${HEAD:0:7}"\n          git push --force origin brand-sync\n          {\n            echo "rnv-brand moved a colour this application uses, at ${HEAD:0:7}."\n            echo\n            echo \'```\'\n            cat sync.log\n            echo \'```\'\n            echo\n            echo "The tests on this change: **$RESULT** (\\`python run_tests.py\\`)."\n            echo\n            echo "Merge to take it; the next build carries it. Image files are not changed."\n          } > body.md\n          if [ "$(gh pr view brand-sync --json state --jq .state 2>/dev/null)" = "OPEN" ]; then\n            gh pr edit brand-sync --title "Brand sync: rnv-brand@${HEAD:0:7}" --body-file body.md\n          else\n            gh pr create --head brand-sync --title "Brand sync: rnv-brand@${HEAD:0:7}" --body-file body.md\n          fi\n', 'COLORS.md': "# Colours: RNV Color Palette Manager\n\nGenerated by `python tools/sync_colors.py` from `brand_map.json`, `ui/colors.py` and rnv-brand at `b4fa970`, the commit pinned in `tests/requirements-dev.txt`. Don't edit it by hand: change the map and run the script. `tests/test_colours_in_sync.py` fails when this file is out of date.\n\n14 colours come from the brand and 17 are the application's own. 12 more are worked out in `ui/colors.py` from those, so they follow them.\n\n## From the brand\n\n| brand name | value | the app's name | made from it in the app |\n|---|---|---|---|\n| `PERMANENT.black` | `#000000` | `TRUE_BLACK` | `APP_WINDOW_OVERLAY` = `translucent(TRUE_BLACK, IMAGE_OVERLAY_ALPHA)` → `#ed000000`<br>`SEARCH_DIM_OVERLAY` = `translucent_tuple(TRUE_BLACK, SEARCH_DIM_ALPHA)` → `(0, 0, 0, 140)`<br>`SIZE_OVERLAY_BG` = `translucent_rgba(TRUE_BLACK, SIZE_OVERLAY_ALPHA)` → `rgba(0, 0, 0, 200)`<br>`PREVIEW_GRID_BORDER` = `_to_rgb(TRUE_BLACK)` → `(0, 0, 0)`<br>`DEFAULT_SLOT_COLOR_IMAGE_RGB` = `translucent_tuple(TRUE_BLACK, SLOT_IMAGE_ALPHA)` → `(0, 0, 0, 171)` |\n| `PERMANENT.white` | `#ffffff` | `WHITE` | — |\n| `APP.panel` | `#1a1a1a` | `BRAND_BLACK` | `APP_PANEL_OVERLAY` = `translucent(BRAND_BLACK, IMAGE_OVERLAY_ALPHA)` → `#ed1a1a1a` |\n| `APP.card` | `#2a2a2a` | `APP_CARD` | — |\n| `APP.panel-hover` | `#3a3a3a` | `APP_PANEL_HOVER` | — |\n| `APP.border` | `#333333` | `APP_BORDER` | — |\n| `APP.text` | `#dddddd` | `APP_TEXT` | — |\n| `APP.text-dim` | `#aaaaaa` | `APP_TEXT_DIM` | — |\n| `APP.surface-light-3` | `#f5f5f5` | `APP_SURFACE_LIGHT_3` | — |\n| `APP.hover-light` | `#eeeeee` | `APP_HOVER_LIGHT` | — |\n| `APP.accent` | `#d2bc93` | `BRAND_GOLD` | `BRAND_GOLD_HOVER` = `lighten(BRAND_GOLD, 13)` → `#dfc9a0`<br>`BRAND_GOLD_RGB` = `_to_rgb(BRAND_GOLD)` → `(210, 188, 147)` |\n| `APP.accent-light-mode` | `#8c7337` | `BRAND_DARK_GOLD` | `BRAND_DARK_GOLD_DEEP` = `lighten(BRAND_DARK_GOLD, -14)` → `#7e6529`<br>`BRAND_DARK_GOLD_RGB` = `_to_rgb(BRAND_DARK_GOLD)` → `(140, 115, 55)` |\n| `STATUS.error-text` | `#dd6f77` | `STATUS_ERROR_TEXT` | — |\n| `STATUS.error-text-light` | `#ae4650` | `STATUS_ERROR_TEXT_LIGHT` | — |\n\n## The application's own\n\n| the app's name | value | why | made from it in the app |\n|---|---|---|---|\n| `GREY_44` | `#444444` | grey(4) on the register's ink grid, which the register states as a rule and does not name. The pressed plate and the scrollbar handle (RNV-COLLAPSE-505050). | `SLOT_BORDER_THIN_COLOR` = `_to_rgb(GREY_44)` → `(68, 68, 68)`<br>`HISTORY_SWATCH_BORDER` = `_to_rgb(GREY_44)` → `(68, 68, 68)` |\n| `GREY_EE` | `#eeeeee` | grey(14) on the ink grid. Static light surfaces, a list header and a scroll ground, that share hover-light's hex without being a hover. | — |\n| `GREY_CC` | `#cccccc` | grey(12) on the ink grid. The light-mode border. | — |\n| `GREY_88` | `#888888` | grey(8) on the ink grid. Muted text on dark; a scrollbar handle's hover on light. | — |\n| `GREY_55` | `#555555` | grey(5) on the ink grid. Disabled text and a checkbox edge on dark. | — |\n| `SELECTION_OVERLAY_COLOR` | `rgba(0,120,215,200)` | The blue overlay drawn during gradient and contrast selection, painted where no theme palette reaches. | — |\n| `GREY_66` | `#666666` | grey(6) on the ink grid. Muted text in light mode. | — |\n| `SEARCH_HIGHLIGHT_COLOR` | `(0, 255, 100)` | The bright green border on slots that match a search. | — |\n| `SLOT_BORDER_THICK_COLOR` | `(60, 60, 60)` | The thick slot border. | — |\n| `SVG_EXPORT_BG` | `#ffffff` | Data, not chrome: the background of an exported SVG palette file. White by meaning, so it does not follow the brand's white. | — |\n| `SVG_EXPORT_STROKE` | `#000000` | Data, not chrome: the swatch stroke in an exported SVG palette file. | — |\n| `DATA_DEFAULT_COLOR` | `#000000` | Data, not chrome: the value a colour record starts with. | — |\n| `SESSION_FALLBACK_COLOR` | `#a9a9a9` | Data: the grey a restored session or a reset setting falls back to. | — |\n| `SESSION_FALLBACK_COLOR_IMAGE` | `#000000` | Data: the image-mode fallback for a reset setting. | — |\n| `CLIPBOARD_PREVIEW_COLOR` | `#4a90d9` | Data, not chrome: the example the settings dialog previews the hex and rgb() clipboard formats with, text shown to the person (#56 A). | — |\n| `TRANSPARENT_RGBA` | `(0, 0, 0, 0)` | Fully transparent: ghost pixmaps and cleared palettes. | — |\n| `DEFAULT_SLOT_COLOR` | `#a9a9a9` | The colour a new slot starts with in dark and light mode. | — |\n\n## What each palette key takes\n\n| key | Dark | Light | Image |\n|---|---|---|---|\n| `window_bg` | `TRUE_BLACK` `#000000` | `APP_SURFACE_LIGHT_3` `#f5f5f5` | `APP_WINDOW_OVERLAY` `#ed000000` |\n| `panel_bg` | `BRAND_BLACK` `#1a1a1a` | `APP_SURFACE_LIGHT_3` `#f5f5f5` | `APP_PANEL_OVERLAY` `#ed1a1a1a` |\n| `scroll_bg` | `TRUE_BLACK` `#000000` | `GREY_EE` `#eeeeee` | `APP_WINDOW_OVERLAY` `#ed000000` |\n| `card_bg` | `APP_CARD` `#2a2a2a` | `WHITE` `#ffffff` | as dark |\n| `input_bg` | `BRAND_BLACK` `#1a1a1a` | `WHITE` `#ffffff` | as dark |\n| `text_color` | `APP_TEXT` `#dddddd` | `TRUE_BLACK` `#000000` | as dark |\n| `text_secondary` | `GREY_88` `#888888` | `GREY_66` `#666666` | as dark |\n| `text_disabled` | `GREY_55` `#555555` | `APP_TEXT_DIM` `#aaaaaa` | as dark |\n| `border_color` | `APP_BORDER` `#333333` | `GREY_CC` `#cccccc` | as dark |\n| `main_btn_bg` | `BRAND_BLACK` `#1a1a1a` | `WHITE` `#ffffff` | as dark |\n| `main_btn_text` | `APP_TEXT` `#dddddd` | `TRUE_BLACK` `#000000` | as dark |\n| `main_btn_hover_bg` | `APP_BORDER` `#333333` | `APP_BORDER` `#333333` | as dark |\n| `main_btn_hover_text` | `APP_TEXT` `#dddddd` | `TRUE_BLACK` `#000000` | as dark |\n| `main_btn_pressed_bg` | `GREY_44` `#444444` | `GREY_44` `#444444` | as dark |\n| `main_btn_pressed_text` | `TRUE_BLACK` `#000000` | `WHITE` `#ffffff` | as dark |\n| `dialog_btn_hover_bg` | `APP_PANEL_HOVER` `#3a3a3a` | `APP_HOVER_LIGHT` `#eeeeee` | as dark |\n| `dialog_btn_bg` | `BRAND_BLACK` `#1a1a1a` | `WHITE` `#ffffff` | as dark |\n| `dialog_btn_text` | `APP_TEXT` `#dddddd` | `TRUE_BLACK` `#000000` | as dark |\n| `scroll_handle` | `GREY_44` `#444444` | `APP_TEXT_DIM` `#aaaaaa` | as dark |\n| `accent` | `BRAND_GOLD` `#d2bc93` | `BRAND_DARK_GOLD` `#8c7337` | as dark |\n| `accent_dark` | `BRAND_GOLD_HOVER` `#dfc9a0` | `BRAND_DARK_GOLD` `#8c7337` | as dark |\n| `accent_ink` | `BRAND_GOLD` `#d2bc93` | `BRAND_DARK_GOLD_DEEP` `#7e6529` | as dark |\n| `scrollbar_bg` | `BRAND_BLACK` `#1a1a1a` | `APP_SURFACE_LIGHT_3` `#f5f5f5` | `transparent` |\n| `scrollbar_handle` | `GREY_44` `#444444` | `APP_TEXT_DIM` `#aaaaaa` | `translucent(GREY_44, SCROLLBAR_HANDLE_ALPHA)` `#96444444` |\n| `scrollbar_handle_hover` | `BRAND_GOLD` `#d2bc93` | `BRAND_DARK_GOLD` `#8c7337` | as dark |\n| `scrollbar_border` | `APP_BORDER` `#333333` | `GREY_CC` `#cccccc` | `translucent(APP_BORDER, SCROLLBAR_BORDER_ALPHA)` `#64333333` |\n| `dialog_bg` | `BRAND_BLACK` `#1a1a1a` | `APP_SURFACE_LIGHT_3` `#f5f5f5` | as dark |\n\nWhich widgets each key reaches is in the fleet chart, *RNV Colour Chart*.\n", 'brand_map.json': '{\n  "about": "Where each colour in ui/colors.py comes from. A string is a name in rnv-brand (TABLE.key, or one of its own constants, in engine/brand.py); an object is a value this application owns, with the reason. Edit this file, then run: python tools/sync_colors.py",\n  "app": "RNV Color Palette Manager",\n  "colour_file": "ui/colors.py",\n  "colours": {\n    "BRAND_GOLD": "APP.accent",\n    "BRAND_DARK_GOLD": "APP.accent-light-mode",\n    "TRUE_BLACK": "PERMANENT.black",\n    "WHITE": "PERMANENT.white",\n    "BRAND_BLACK": "APP.panel",\n    "APP_CARD": "APP.card",\n    "APP_BORDER": "APP.border",\n    "APP_TEXT": "APP.text",\n    "APP_TEXT_DIM": "APP.text-dim",\n    "APP_PANEL_HOVER": "APP.panel-hover",\n    "GREY_44": {\n      "app": "#444444",\n      "why": "grey(4) on the register\'s ink grid, which the register states as a rule and does not name. The pressed plate and the scrollbar handle (RNV-COLLAPSE-505050)."\n    },\n    "APP_HOVER_LIGHT": "APP.hover-light",\n    "APP_SURFACE_LIGHT_3": "APP.surface-light-3",\n    "GREY_EE": {\n      "app": "#eeeeee",\n      "why": "grey(14) on the ink grid. Static light surfaces, a list header and a scroll ground, that share hover-light\'s hex without being a hover."\n    },\n    "GREY_CC": {\n      "app": "#cccccc",\n      "why": "grey(12) on the ink grid. The light-mode border."\n    },\n    "GREY_88": {\n      "app": "#888888",\n      "why": "grey(8) on the ink grid. Muted text on dark; a scrollbar handle\'s hover on light."\n    },\n    "GREY_55": {\n      "app": "#555555",\n      "why": "grey(5) on the ink grid. Disabled text and a checkbox edge on dark."\n    },\n    "SELECTION_OVERLAY_COLOR": {\n      "app": "rgba(0,120,215,200)",\n      "why": "The blue overlay drawn during gradient and contrast selection, painted where no theme palette reaches."\n    },\n    "GREY_66": {\n      "app": "#666666",\n      "why": "grey(6) on the ink grid. Muted text in light mode."\n    },\n    "SEARCH_HIGHLIGHT_COLOR": {\n      "app": [0, 255, 100],\n      "why": "The bright green border on slots that match a search."\n    },\n    "SLOT_BORDER_THICK_COLOR": {\n      "app": [60, 60, 60],\n      "why": "The thick slot border."\n    },\n    "STATUS_ERROR_TEXT": "STATUS.error-text",\n    "STATUS_ERROR_TEXT_LIGHT": "STATUS.error-text-light",\n    "SVG_EXPORT_BG": {\n      "app": "#ffffff",\n      "why": "Data, not chrome: the background of an exported SVG palette file. White by meaning, so it does not follow the brand\'s white."\n    },\n    "SVG_EXPORT_STROKE": {\n      "app": "#000000",\n      "why": "Data, not chrome: the swatch stroke in an exported SVG palette file."\n    },\n    "DATA_DEFAULT_COLOR": {\n      "app": "#000000",\n      "why": "Data, not chrome: the value a colour record starts with."\n    },\n    "SESSION_FALLBACK_COLOR": {\n      "app": "#a9a9a9",\n      "why": "Data: the grey a restored session or a reset setting falls back to."\n    },\n    "SESSION_FALLBACK_COLOR_IMAGE": {\n      "app": "#000000",\n      "why": "Data: the image-mode fallback for a reset setting."\n    },\n    "CLIPBOARD_PREVIEW_COLOR": {\n      "app": "#4a90d9",\n      "why": "Data, not chrome: the example the settings dialog previews the hex and rgb() clipboard formats with, text shown to the person (#56 A)."\n    },\n    "TRANSPARENT_RGBA": {\n      "app": [0, 0, 0, 0],\n      "why": "Fully transparent: ghost pixmaps and cleared palettes."\n    },\n    "DEFAULT_SLOT_COLOR": {\n      "app": "#a9a9a9",\n      "why": "The colour a new slot starts with in dark and light mode."\n    }\n  }\n}\n', 'tests/colour_values.py': '"""Every colour value the tests need that is not one of the application\'s own.\n\nRNV-COLOUR-SYNC (#53 A), 2026-10-17. The application\'s colours, brand and its\nown, are named in ui/colors.py, which brand_map.json names, and a test reads\nthem from there. Every other colour value a test or the root suite writes is\nnamed here, once, with why, grouped by kind. tests/test_colour_values.py holds\nthis file: no colour value is written anywhere else, each name says what kind\nit is and why, each is used, and each REGISTER_ value is the brand\'s at the pin.\n\nTests under tests/ read it as `from colour_values import ...`; the root suite,\nrun from the repository root, as `from tests.colour_values import ...`.\n\nRNV-COLLAPSE-GUARD\n    tests/test_collapse_505050.py sweeps every evaluated string for #505050 in\n    any spelling and skips files carrying this; this file names it, as OLD_HEX\n    and in each spelling the decoder must read, in order to forbid it.\nRNV-GOLD-GUARD-FILE-NAMES-RETIRED-VALUES-BY-DESIGN\n    tests/test_brand_mirror.py scans raw text for the retired dark gold #b19145\n    and its two tuple spellings, and skips files carrying this; this file names\n    them as that guard\'s RETIRED list.\nRNV-NAME-GUARD\n    tests/test_constant_names.py sweeps raw text for the retired Windows blue,\n    quoted, and skips files carrying this; this file names it as\n    RETIRED_WINDOWS_BLUE, which that sweep\'s pattern is built from.\n"""\n\n# ---------------------------------------------------------------------------\n# Examples: samples given to a helper, a reader or the colour maths\n# ---------------------------------------------------------------------------\n\nEXAMPLE_BLACK = "#000000"\n"""Pure black as a sample: a ColorMath conversion\'s input or output, a ground\nfor contrast() and contrast_ink(), and what a reader or the integer sweep makes\nof black in its self-test. It equals TRUE_BLACK and does not mean it."""\n\nEXAMPLE_BLACK_SHORT = "#000"\n"""Black in three digits, written in the ink guard\'s sample sheet; the reader\nmust expand it to EXAMPLE_BLACK."""\n\nEXAMPLE_BLACK_BARE = "000000"\n"""The six digits the ARGB reader in tests/test_error_red.py must take from\nEXAMPLE_ARGB_BLACK_AT_ED: alpha dropped, no hash."""\n\nEXAMPLE_WHITE = "#ffffff"\n"""Pure white as a sample: a ColorMath conversion\'s input or output, a ground\nfor contrast() and contrast_ink(), and what the ink guard\'s reader makes of\n`white`. It equals WHITE and does not mean it."""\n\nEXAMPLE_WHITE_SHORT = "#fff"\n"""White in three digits: hex_to_rgb must expand the shorthand."""\n\nEXAMPLE_RED = "#ff0000"\n"""(255, 0, 0) as rgb_to_hex writes it."""\n\nEXAMPLE_RED_UPPER = "#FF0000"\n"""The same red in upper case: hex_to_rgb must read either case."""\n\nEXAMPLE_RED_SHORT = "#f00"\n"""The same red in three digits: hex_to_rgb must expand the shorthand."""\n\nEXAMPLE_RED_BARE = "ff0000"\n"""The same red with no hash: hex_to_rgb must take it."""\n\nEXAMPLE_GREEN = "#00ff00"\n"""(0, 255, 0) as rgb_to_hex writes it."""\n\nEXAMPLE_BLUE = "#0000ff"\n"""(0, 0, 255) as rgb_to_hex writes it."""\n\nEXAMPLE_SHORT_GREY = "#555"\n"""A three-digit grey the collapse guard\'s decoder must expand. The point is\nthe shorthand, not the grey."""\n\nEXAMPLE_SHORT_GREY_EXPANDED = "#555555"\n"""What the decoder must make of EXAMPLE_SHORT_GREY. It equals GREY_55 and does\nnot mean it."""\n\nEXAMPLE_ARGB_ALPHA_FIRST = "#96444444"\n"""An eight-digit #AARRGGBB the collapse guard\'s decoder must read ALPHA FIRST.\nIt equals image mode\'s scrollbar handle today; the test is of the decoder, so\nit must not follow the palette."""\n\nEXAMPLE_ARGB_ALPHA_FIRST_DECODED = "#444444"\n"""The colour EXAMPLE_ARGB_ALPHA_FIRST holds once its alpha is taken off the\nfront."""\n\nEXAMPLE_ARGB_ALPHA_FIRST_MISREAD = "#964444"\n"""What EXAMPLE_ARGB_ALPHA_FIRST becomes if the first six digits are taken\ninstead of the last: a real colour and the wrong one."""\n\nEXAMPLE_HAND_EDIT = "#123456"\n"""A value a person might type over a colour file line by hand, which the sync\nmust put back; and the colour of a constant the map does not hold."""\n\nEXAMPLE_HAND_EDIT_FALLBACK = "#654321"\n"""The hand edit to use when the line already holds EXAMPLE_HAND_EDIT."""\n\nEXAMPLE_MOVED_ACCENT = "#6f94bc"\n"""A hypothetical new value for the brand\'s accent, to show a brand move reaches\nthe one line that takes it."""\n\nEXAMPLE_MOVED_ACCENT_FALLBACK = "#456c91"\n"""The moved accent to use when the accent already is EXAMPLE_MOVED_ACCENT."""\n\nEXAMPLE_CHARCOAL = "#1a1a1a"\n"""A base handed to translucent() and translucent_rgba(). It equals BRAND_BLACK\ntoday; the composed values the tests expect are written out, so the base must\nnot follow the brand. Lower case: the round trip compares it as written."""\n\nEXAMPLE_CHARCOAL_BARE_UPPER = "1A1A1A"\n"""EXAMPLE_CHARCOAL with no hash and in upper case, both of which translucent()\naccepts and lower-cases."""\n\nEXAMPLE_CHARCOAL_AT_ED = "#ed1a1a1a"\n"""translucent(EXAMPLE_CHARCOAL, 0xED): eight digits, alpha first, lower case."""\n\nEXAMPLE_CHARCOAL_RGBA_191 = "rgba(26, 26, 26, 191)"\n"""translucent_rgba(EXAMPLE_CHARCOAL, 191), in the spelling it writes."""\n\nEXAMPLE_BLACK_RGBA_200 = "rgba(0, 0, 0, 200)"\n"""translucent_rgba(EXAMPLE_BLACK, 0xC8), in the spelling it writes. It equals\nSIZE_OVERLAY_BG and does not mean it: the test is of the helper."""\n\nEXAMPLE_TAN = "#d2bc93"\n"""A base handed to the alpha helpers. It equals BRAND_GOLD today and must not\nfollow it: the composed value the test expects is written out."""\n\nEXAMPLE_TAN_AT_33 = "#33d2bc93"\n"""translucent(EXAMPLE_TAN, 0x33)."""\n\nEXAMPLE_MID_GREY = "#444444"\n"""A base for the alpha helpers\' round trip, and what the integer sweep reads\nfrom its probe\'s QColor(68, 68, 68). It equals GREY_44 and does not mean it."""\n\nEXAMPLE_ARGB_BLACK_AT_ED = "#ed000000"\n"""An eight-digit #AARRGGBB the ARGB reader in tests/test_error_red.py must not\nread as EXAMPLE_ARGB_BLACK_AT_ED_MISREAD. It equals image mode\'s window ground\ntoday; the test is of the reader."""\n\nEXAMPLE_ARGB_BLACK_AT_ED_MISREAD = "#ed0000"\n"""What EXAMPLE_ARGB_BLACK_AT_ED becomes read naively as #RRGGBB: a red. The\ncontrast against it computes to 1.6448 instead of the ~7.57 the eye sees."""\n\nEXAMPLE_OFF_WHITE = "#f5f5f5"\n"""A six-digit value the ARGB reader must pass through unchanged. It equals\nAPP_SURFACE_LIGHT_3 and does not mean it."""\n\nEXAMPLE_OFF_WHITE_BARE = "f5f5f5"\n"""What the ARGB reader gives back for EXAMPLE_OFF_WHITE: its six digits."""\n\nEXAMPLE_SWEEP_PROBE_HEX = "#ffcccc"\n"""The hex in the named-and-used sweep\'s probe line, which the sweep must report,\nand in the probe\'s prose, which it must not."""\n\nEXAMPLE_SWEEP_PROBE_RGBA = "rgba(255, 255, 255, 230)"\n"""The rgba() in the named-and-used sweep\'s probe line, in the single-spaced form\nthe sweep reports it in."""\n\nEXAMPLE_CLEAR_RGBA = "rgba(0, 0, 0, 0)"\n"""Clear: alpha 0, how a widget is told to paint nothing. The named-and-used\nsweep\'s quiet probe holds it, and the sweep must not report it as a colour."""\n\nEXAMPLE_STATUS_ERROR_LIGHTENED = "#b44753"\n"""lighten(REGISTER_STATUS_ERROR, -20): what the retired rule for the light\nerror text yields against the register\'s error base since 2026-09-03. Neither\nthe old RETIRED_ERROR_TEXT_LIGHT_ORPHAN nor the registered value; a third\nanswer, which is why the light error text is registered, not derived."""\n\nEXAMPLE_BENCH_PURPLE = "#7B2DC8"\n"""The input to the hex_to_rgb benchmark, in upper case: (123, 45, 200), the\ncolour the other conversion benchmarks use."""\n\n# ---------------------------------------------------------------------------\n# Data: what a user, the search box, a record or the settings supply\n# ---------------------------------------------------------------------------\n\nDATA_QUERY_RED = "#ff0000"\n"""Red typed into the search box, as parse_color_query reads it."""\n\nDATA_QUERY_RED_UPPER = "#FF0000"\n"""The same search in upper case."""\n\nDATA_QUERY_RED_SHORT = "#f00"\n"""The same search in three digits."""\n\nDATA_QUERY_RED_BARE = "ff0000"\n"""The same search with no hash, as the main window\'s search box receives it."""\n\nDATA_QUERY_RED_PADDED = "  #ff0000  "\n"""The same search with spaces round it, which the parser must strip. The spaces\nare the point."""\n\nDATA_QUERY_GREEN_BARE = "00ff00"\n"""Green typed into the search box with no hash."""\n\nDATA_QUERY_GREEN_RGB = "rgb(0,255,0)"\n"""Green typed as rgb() with no spaces, which is the case the test is about."""\n\nDATA_QUERY_WHITE_SHORT = "#fff"\n"""White typed into the search box in three digits."""\n\nDATA_HEX_INPUT_ORANGE = "#FF8800"\n"""A valid hex as a person types it, for ValidationHelper.validate_hex_color."""\n\nDATA_HEX_INPUT_ORANGE_BARE = "FF8800"\n"""The same hex typed with no hash, which validate_hex_color accepts."""\n\nDATA_HEX_INPUT_ORANGE_SHORT = "#F80"\n"""The same orange typed in three digits, which validate_hex_color accepts."""\n\nDATA_HISTORY_BLACK = "#000000"\n"""A slot change\'s colour in a colour-history record. It equals TRUE_BLACK and\ndoes not mean it: a record holds what the user chose."""\n\nDATA_HISTORY_WHITE = "#ffffff"\n"""A slot change\'s colour in a colour-history record. It equals WHITE and does\nnot mean it."""\n\nDATA_HISTORY_BLACK_SHORT = "#000"\n"""Black as a colour-history record or a session\'s history holds it, in three\ndigits."""\n\nDATA_HISTORY_WHITE_SHORT = "#fff"\n"""White as a colour-history record or a session\'s history holds it, in three\ndigits."""\n\nDATA_HISTORY_SLATE = "#aabbcc"\n"""A slot change\'s old colour in a colour-history record."""\n\nDATA_HISTORY_NAVY = "#112233"\n"""A slot change\'s new colour in a colour-history record."""\n\nDATA_HISTORY_PALE_BLUE = "#ddeeff"\n"""A slot change\'s new colour in a history entry\'s round trip."""\n\nDATA_HISTORY_DARK_RED = "#aa0000"\n"""A slot change\'s old colour, for the history\'s list round trip."""\n\nDATA_HISTORY_GREEN = "#00aa00"\n"""A slot change\'s new colour, for the history\'s list round trip."""\n\nDATA_HISTORY_GREY_1 = "#111111"\n"""The first of four distinct history colours, recorded oldest first, for the\nnewest-first check."""\n\nDATA_HISTORY_GREY_2 = "#222222"\n"""The second of the four history colours."""\n\nDATA_HISTORY_GREY_3 = "#333333"\n"""The third of the four history colours. It equals APP_BORDER and does not\nmean it."""\n\nDATA_HISTORY_GREY_4 = "#444444"\n"""The last of the four history colours, which must come back first. It equals\nGREY_44 and does not mean it."""\n\nDATA_SETTINGS_SLOT_COLOR = "#123456"\n"""A default slot colour a person sets for dark mode, round-tripped through\nSettingsManager."""\n\nDATA_SLOT_RED = "#ff0000"\n"""A red slot\'s colour: what a saved session and an undo state hold beside its\nchannels (255, 0, 0), and what a slot made from those channels must paint."""\n\nDATA_SLOT_BLACK = "#000000"\n"""A slot\'s hex as an undo state holds it, beside its channels (0, 0, 0)."""\n\nDATA_IMAGE_YELLOW = "#ffff00"\n"""The fill of an image set on a slot, from its channels (255, 255, 0), which the\nslot must paint in place of its own colour."""\n\n# ---------------------------------------------------------------------------\n# Retired: values the application no longer uses, kept so a test can say so\n# ---------------------------------------------------------------------------\n\nRETIRED_OLD_DARK_GOLD = "#b19145"\n"""The old light-mode gold, retired 2026-08-17: 2.997638 on white, under every\nfloor it claimed. Lower case: the gold guard compares lower-cased text."""\n\nRETIRED_OLD_DARK_GOLD_RGB_SPACED = "(177, 145, 69)"\n"""The old gold as the RGB tuple a hex census cannot see, written with spaces,\nas the gold guard searches raw text for it."""\n\nRETIRED_OLD_DARK_GOLD_RGB_TIGHT = "(177,145,69)"\n"""The same tuple without spaces."""\n\nRETIRED_OLD_HOVER_GOLD = "#c4a458"\n"""The hover tint once written out beside RETIRED_OLD_DARK_GOLD. When that base\nmoved, the tint stayed behind: a value derived from something no longer in the\npalette, the failure every "derived, not written" rule in this fleet cites."""\n\nRETIRED_GREY_E0 = "#e0e0e0"\n"""APP["text"] until 2026-08-28, and two light surfaces nothing read: one hex\ndoing two jobs. The ink moved to APP_TEXT; the surfaces went on 2026-10-04."""\n\nRETIRED_GREY_50 = "#505050"\n"""The handle and plate grey ruled onto GREY_44 (RNV-COLLAPSE-505050), the\ncollapse guard\'s OLD_HEX."""\n\nRETIRED_GREY_50_DIGITS = "505050"\n"""Its six digits, which no spelling of image mode\'s scrollbar handle may hold."""\n\nRETIRED_GREY_50_ARGB_96 = "#96505050"\n"""The retired grey at alpha 0x96, alpha first, for the decoder\'s self-test."""\n\nRETIRED_GREY_50_ARGB_FF_UPPER = "#FF505050"\n"""The retired grey opaque, alpha first, in upper case on purpose: the decoder\nmust read either case."""\n\nRETIRED_GREY_50_RGBA_100 = "rgba(80, 80, 80, 100)"\n"""The exact spelling image mode painted its scrollbar handle in until\n2026-09-25, while the first version of the collapse guard reported it gone."""\n\nRETIRED_GREY_50_RGBA_FRACTION = "rgba(80,80,80,0.6)"\n"""The retired grey as a compact rgba() with a fractional alpha."""\n\nRETIRED_GREY_50_RGB = "rgb(80, 80, 80)"\n"""The retired grey as rgb()."""\n\nRETIRED_SCROLLBAR_BORDER_LITERAL = "rgba(51, 51, 51, 100)"\n"""The literal image mode\'s scrollbar border was written as until 2026-09-25,\nwhose alpha SCROLLBAR_BORDER_ALPHA keeps. Now translucent(APP_BORDER, ...)."""\n\nRETIRED_SIZE_OVERLAY_LITERAL = "rgba(0, 0, 0, 200)"\n"""The literal the size overlay was written as until 2026-09-25, whose alpha\nSIZE_OVERLAY_ALPHA keeps. SIZE_OVERLAY_BG still spells the same, now derived;\nthis records the literal, and does not follow it."""\n\nRETIRED_SLOT_IMAGE_LITERAL = "rgba(0, 0, 0, 171)"\n"""The literal a new image-mode slot\'s fill was written as, whose alpha\nSLOT_IMAGE_ALPHA keeps."""\n\nRETIRED_WINDOW_OVERLAY_LITERAL = "#ED000000"\n"""The literal APP_WINDOW_OVERLAY was written as until 2026-09-24, in upper\ncase. The six-digit sweep of 2026-08-29 never matched it to TRUE_BLACK, and\nRNV-LOWER-EIGHT (2026-09-25) writes eight digits in lower case."""\n\nRETIRED_PANEL_OVERLAY_LITERAL = "#ED1A1A1A"\n"""The literal APP_PANEL_OVERLAY was written as until 2026-09-24, in upper\ncase, which RNV-LOWER-EIGHT retired."""\n\nRETIRED_GREY_D0 = "#d0d0d0"\n"""The light hover plate rnv-brand retired as an interaction ground: gold text\non it read 3.6013. Lower case: the test compares lower-cased values."""\n\nRETIRED_GREY_FA = "#fafafa"\n"""A light stray collapsed onto the register\'s surface-light-2 on 2026-09-06."""\n\nRETIRED_GREY_F8 = "#f8f8f8"\n"""A light stray collapsed onto the register\'s surface-light-2 on 2026-09-06."""\n\nRETIRED_GREY_F0 = "#f0f0f0"\n"""The light stray ui/image_upload_dialog.py painted, collapsed onto GREY_EE on\n2026-09-06."""\n\nRETIRED_MATERIAL_RED = "#f44336"\n"""Material\'s red, a palette\'s dead \'error\' entry until it was ruled out.\nLower case: the tests compare lower-cased values."""\n\nRETIRED_MATERIAL_GREEN = "#4caf50"\n"""Material\'s green, ruled out as a status value 2026-09-02."""\n\nRETIRED_OWN_DARK_ERROR_TEXT = "#ff6b6b"\n"""This application\'s own dark error text, ruled out 2026-09-02 for the\nregister\'s."""\n\nRETIRED_BOOTSTRAP_GREEN = "#28a745"\n"""Bootstrap\'s success green, retired by the register 2026-09-03\n(RNV-STATUS-FAMILY)."""\n\nRETIRED_BOOTSTRAP_AMBER = "#ffc107"\n"""Bootstrap\'s warning amber, retired 2026-09-03."""\n\nRETIRED_BOOTSTRAP_RED = "#dc3545"\n"""Bootstrap\'s error red, retired 2026-09-03; the base of the two orphans below."""\n\nRETIRED_ERROR_TEXT_ORPHAN = "#e56b77"\n"""The dark error text derived from RETIRED_BOOTSTRAP_RED, retired with it."""\n\nRETIRED_ERROR_TEXT_LIGHT_ORPHAN = "#c82131"\n"""The light error text derived from RETIRED_BOOTSTRAP_RED, retired with it. It\nread 4.6100 on REGISTER_GOLD_TEXT_GROUND_FLOOR."""\n\nRETIRED_REV30_SUCCESS_TEXT_LIGHT = "#8a6581"\n"""The register\'s light success text at rev 30, walked against\nAPP_SURFACE_LIGHT_3; rev 31 re-walked it against\nREGISTER_GOLD_TEXT_GROUND_FLOOR. This application never drew it."""\n\nRETIRED_REV30_WARNING_TEXT_LIGHT = "#976633"\n"""The register\'s light warning text at rev 30, re-walked at rev 31. This\napplication never drew it."""\n\nRETIRED_REV30_ERROR_TEXT_LIGHT = "#b84e58"\n"""The register\'s light error text at rev 30, which read 4.0150 on\nREGISTER_GOLD_TEXT_GROUND_FLOOR; rev 31 re-walked it to STATUS_ERROR_TEXT_LIGHT."""\n\nRETIRED_CSS_GREY = "#808080"\n"""The CSS `grey` six muted labels in two dialogs were written in, in every\nmode, until RNV-MUTED-DESCRIPTIONS (2026-09-27) drew them in text_secondary."""\n\nRETIRED_WINDOWS_BLUE = "#0078d4"\n"""The Windows blue a constant nothing used held until 2026-09-02: on no ladder,\nno grid and no brand."""\n\n# ---------------------------------------------------------------------------\n# Register: values the brand publishes that this application does not draw\n# ---------------------------------------------------------------------------\n\nREGISTER_GOLD_TEXT_GROUND_FLOOR = "#e8e8e8"\n"""The darkest light ground the gold family carries text on, and the floor the\nlight status texts were re-walked to. The application draws no ground at it.\nLower case: the tests compare lower-cased values."""\n\nREGISTER_APP_SURFACE_LIGHT_2 = "#fbfbfb"\n"""The register\'s second light surface rung: a rung the light texts are measured\non, and the rung two light strays collapsed onto. This application draws none."""\n\nREGISTER_APP_PRESSED_LIGHT = "#e0e0e0"\n"""The register\'s light pressed plate, where no brand text carries: the boundary\nthe light texts are held to fail at."""\n\nREGISTER_STATUS_ERROR = "#c75b64"\n"""The register\'s error fill, which this application does not carry: the base\nthe light error text is shown not to be derived from."""\n\n# ---------------------------------------------------------------------------\n# Invalid: written wrongly on purpose, for a test that refuses it\n# ---------------------------------------------------------------------------\n\nINVALID_HEX_FIVE_DIGITS = "#12345"\n"""Five digits: validate_hex_color must refuse it and the collapse decoder must\nnot read a colour in it."""\n\nINVALID_HEX_FOUR_DIGITS = "#FF88"\n"""Four digits, which validate_hex_color must refuse for its length."""\n\nINVALID_HEX_NOT_HEX = "#GG8800"\n"""Six characters, two of them not hex digits."""\n\nINVALID_HEX_NOT_HEX_BARE = "ZZZZZZ"\n"""Six characters with no hash, none of them hex digits."""\n\nINVALID_BASE_FIVE_DIGITS = "#1a1a1"\n"""A base one digit short, which translucent() and translucent_rgba() refuse."""\n\nINVALID_BASE_EIGHT_DIGITS = "#1a1a1a1a"\n"""A base that already carries an alpha, which the alpha helpers refuse."""\n\nINVALID_BASE_NOT_HEX = "#gggggg"\n"""A base of six characters that are not hex digits."""\n\n# ---------------------------------------------------------------------------\n\nREGISTER_REFS = {\n    "REGISTER_GOLD_TEXT_GROUND_FLOOR": "GOLD_TEXT_GROUND_FLOOR",\n    "REGISTER_APP_SURFACE_LIGHT_2": "APP.surface-light-2",\n    "REGISTER_APP_PRESSED_LIGHT": "APP.pressed-light",\n    "REGISTER_STATUS_ERROR": "STATUS.error",\n}\n"""Each REGISTER_ value\'s name in the brand; tests/test_colour_values.py holds\nthe value to the brand at the pin."""\n', 'tests/test_colour_values.py': '"""Every colour value the tests use is named once.   RNV-COLOUR-SYNC (#53 A)\n\nInstalled 2026-10-17, ruled in #52 to #57. The application\'s own colours and\nthe brand\'s are named in the colour file, which brand_map.json names, and a\ntest reads them from there. Every other colour value a test needs is named in\ntests/colour_values.py, once, with why:\n\n  EXAMPLE_   a sample given to a helper or to the colour maths\n  DATA_      what a user, a file, the clipboard or the search box supplies\n  RETIRED_   a value the application no longer uses, kept so a test can say so\n  REGISTER_  a value the brand publishes that this application does not draw;\n             REGISTER_REFS says which brand name, and this file holds it there\n  INVALID_   a value written wrongly on purpose, for a test that refuses it\n\nWHAT THIS GUARD HOLDS.\n\n1. No test under tests/, and no root suite, writes a colour value anywhere\n   but tests/colour_values.py: a string that is only a colour -- a hex code\n   of three, six or eight digits, or an rgb() or rgba() value (#54 A).\n2. No sentence in a test -- a comment, a docstring, a message -- writes a hex\n   code or an rgb() value either. It says the name, and a message prints the\n   value through it, in an f-string (#57 A). What a value is, and why it was\n   retired, is said once, beside it, in tests/colour_values.py.\n3. The readers are looking: they find every value in tests/colour_values.py,\n   and a planted sentence.\n4. Every name there says what kind it is, says why, and is used by a test.\n5. Every REGISTER_ value is the brand\'s, at the pinned commit.\n\nThe same file in all five applications.\n"""\nfrom __future__ import annotations\n\nimport ast\nimport importlib.util\nimport io\nimport json\nimport re\nimport tokenize\nfrom pathlib import Path\n\nimport pytest\n\nROOT = Path(__file__).resolve().parents[1]\nTESTS = ROOT / "tests"\nVALUES_FILE = TESTS / "colour_values.py"\nKINDS = ("EXAMPLE_", "DATA_", "RETIRED_", "REGISTER_", "INVALID_")\nCOLOUR = re.compile(r"^\\s*(?:#(?:[0-9a-fA-F]{8}|[0-9a-fA-F]{6}|[0-9a-fA-F]{3})"\n                    r"|rgba?\\([^()]*\\))\\s*$")\n#: A hex code, or the start of an rgb() value, inside a sentence.\nIN_A_SENTENCE = re.compile(\n    r"(?<![0-9A-Za-z&/])#(?:[0-9a-fA-F]{8}|[0-9a-fA-F]{6}|[0-9a-fA-F]{3})(?![0-9A-Za-z_])"\n    r"|\\brgba?\\(\\s*\\d")\n\n\ndef _load(name: str, path: Path):\n    spec = importlib.util.spec_from_file_location(name, path)\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module\n\n\nVALUES = _load("colour_values_under_guard", VALUES_FILE)\n\n\ndef colour_strings(source: str) -> list[tuple[int, str]]:\n    """(line, value) for every string in the source that is only a colour."""\n    found = []\n    for tok in tokenize.generate_tokens(io.StringIO(source).readline):\n        if tok.type != tokenize.STRING:\n            continue\n        try:\n            value = ast.literal_eval(tok.string)\n        except (ValueError, SyntaxError):\n            continue\n        if isinstance(value, str) and COLOUR.match(value):\n            found.append((tok.start[0], value))\n    return found\n\n\ndef sentence_colours(source: str) -> list[tuple[int, str]]:\n    """(line, text) for every hex code or rgb() value inside a comment, a\n    docstring, a message, or any other string that is not only a colour."""\n    found = []\n    middle = getattr(tokenize, "FSTRING_MIDDLE", None)\n    for tok in tokenize.generate_tokens(io.StringIO(source).readline):\n        if tok.type == tokenize.STRING:\n            try:\n                value = ast.literal_eval(tok.string)\n            except (ValueError, SyntaxError):\n                value = None\n            if isinstance(value, str) and COLOUR.match(value):\n                continue\n        elif tok.type not in (tokenize.COMMENT, middle):\n            continue\n        # An escape such as \\\\n before a hex code would hide it from the\n        # look-behind; read it as the space it stands for.\n        for match in IN_A_SENTENCE.finditer(re.sub(r"\\\\[ntr]", " ", tok.string)):\n            found.append((tok.start[0], match.group(0)))\n    return found\n\n\ndef _test_files() -> list[Path]:\n    files = sorted(p for p in TESTS.rglob("*.py")\n                   if "__pycache__" not in p.parts and p != VALUES_FILE)\n    return files + sorted(ROOT.glob("test_rnv_*.py"))\n\n\ndef _named() -> dict[str, str]:\n    """Each name tests/colour_values.py gives a value, with that value."""\n    return {k: v for k, v in vars(VALUES).items() if k.isupper() and isinstance(v, str)}\n\n\ndef test_no_colour_value_is_written_outside_colour_values():\n    strays = []\n    for path in _test_files():\n        for line, value in colour_strings(path.read_text(encoding="utf-8-sig")):\n            strays.append(f"{path.relative_to(ROOT).as_posix()}:{line} {value!r}")\n    assert not strays, (\n        "a colour value written in a test. Read it from the colour file if it is the "\n        "application\'s colour, or name it in tests/colour_values.py:\\n  " + "\\n  ".join(strays))\n\n\ndef test_no_sentence_in_a_test_writes_a_colour():\n    found = []\n    for path in _test_files():\n        for line, text in sentence_colours(path.read_text(encoding="utf-8-sig")):\n            found.append(f"{path.relative_to(ROOT).as_posix()}:{line} {text!r}")\n    assert not found, (\n        "a hex code or an rgb() value written in a comment, a docstring or a "\n        "message. Say the name, and print the value through it:\\n  " + "\\n  ".join(found))\n\n\ndef test_the_sentence_reader_is_looking():\n    hexes = [VALUES.EXAMPLE_HAND_EDIT, VALUES.EXAMPLE_MOVED_ACCENT]\n    planted = (f"# was {hexes[0]}\\n"\n               f"z = \'one\\\\n{hexes[0]}\'\\n"\n               f"x = f\'{{a}} on {hexes[1]}\'\\n"\n               f"y = \'rgb({0}, {0}, {0}) is not a name\'\\n")\n    assert [t for _, t in sentence_colours(planted)] == [hexes[0]] + hexes + [f"rgb({0}"], \\\n        "the sentence reader misses a hex code in a comment or a message -- it is blind"\n\n\ndef test_the_reader_finds_every_value_in_colour_values():\n    found = {value for _, value in colour_strings(VALUES_FILE.read_text(encoding="utf-8-sig"))}\n    colours = {v for v in _named().values() if COLOUR.match(v)}\n    assert colours, "tests/colour_values.py names no colour -- the reader is blind"\n    assert colours <= found, f"the reader misses {sorted(colours - found)}"\n\n\ndef test_every_name_says_what_kind_it_is():\n    wrong = sorted(n for n in _named() if not n.startswith(KINDS))\n    assert not wrong, f"names without one of {KINDS}: {wrong}"\n\n\ndef test_every_name_says_why():\n    body = ast.parse(VALUES_FILE.read_text(encoding="utf-8-sig")).body\n    silent = []\n    for here, after in zip(body, body[1:] + [None]):\n        targets = here.targets if isinstance(here, ast.Assign) else \\\n            [here.target] if isinstance(here, ast.AnnAssign) else []\n        for target in targets:\n            if isinstance(target, ast.Name) and target.id in _named():\n                said = isinstance(after, ast.Expr) and isinstance(after.value, ast.Constant) \\\n                    and isinstance(after.value.value, str) and after.value.value.strip()\n                if not said:\n                    silent.append(target.id)\n    assert not silent, f"names with no docstring under them saying why: {silent}"\n\n\ndef test_every_name_is_used_by_a_test():\n    text = "\\n".join(p.read_text(encoding="utf-8-sig") for p in _test_files())\n    unused = sorted(n for n in _named() if not re.search(rf"\\b{n}\\b", text))\n    assert not unused, f"named in tests/colour_values.py and used by no test: {unused}"\n\n\ndef test_every_register_value_is_the_brands():\n    refs = getattr(VALUES, "REGISTER_REFS", {})\n    names = sorted(n for n in _named() if n.startswith("REGISTER_"))\n    assert sorted(refs) == names, "REGISTER_REFS must name the brand\'s name for each REGISTER_ value"\n    if not names:\n        return\n    sync = _load("sync_colors_for_values", ROOT / "tools" / "sync_colors.py")\n    try:\n        brand, _ = sync.load_brand(ROOT)\n    except sync.SyncError as exc:\n        pytest.fail(str(exc))\n    wrong = {n: (getattr(VALUES, n), sync.brand_value(brand, refs[n])) for n in names\n             if getattr(VALUES, n).lower() != str(sync.brand_value(brand, refs[n])).lower()}\n    assert not wrong, f"not the brand\'s value at the pin (here, brand): {wrong}"\n', 'tests/test_colours_in_sync.py': '"""The colour file is what the brand and the map say it is.   RNV-COLOUR-SYNC\n\nInstalled 2026-10-16, ruled in #36 to #48. brand_map.json says where each\ncolour in this application\'s colour file comes from: a name in rnv-brand, or a\nvalue this application owns, with the reason. tools/sync_colors.py writes the\nvalue on each of those lines from the map and from the brand at the commit\npinned in tests/requirements-dev.txt, and writes COLORS.md, the chart of them.\nThe same two files, this one and the tool, are in all five applications;\nbrand_map.json is what differs.\n\nWHAT THIS REPLACES. Until this date each brand value was written out by hand\nin two places, the colour file and a test beside it, and a brand move meant\nediting both (#39). The tests that wrote a value as its hex code now hold the\nname it takes; this file holds every value, once, against the brand itself.\nThe few sample colours it needs are named in tests/colour_values.py (#53 A).\n\nWHAT THIS GUARD HOLDS.\n\n1. The colour file and COLORS.md are exactly what the sync would write. A\n   value edited by hand, a map entry changed without a sync, or a pin moved\n   without one, and this names the file and says what to run.\n2. Every colour the colour file writes as a value is in the map, and every\n   colour the application owns says why.\n3. The provenance maps in the colour file agree with the map: a register\n   value is a brand name there, an application\'s ramp step or semantic colour\n   is its own, a derived value is code.\n4. The sync is looking: it puts back a value edited by hand, refuses a colour\n   the map does not hold, refuses a derived colour in the map, refuses a\n   brand that is not the pinned one, and carries a brand move to the one line\n   that takes it.\n5. The daily workflow runs the sync against the brand\'s head and opens a pull\n   request only when the colour file moved.\n"""\nfrom __future__ import annotations\n\nimport importlib\nimport importlib.util\nimport pathlib\nimport re\nimport types\n\nimport pytest\n\nROOT = pathlib.Path(__file__).resolve().parents[1]\nWORKFLOW = ROOT / ".github" / "workflows" / "brand-sync.yml"\n\n\ndef _sync():\n    """tools/sync_colors.py, loaded by path: tools/ is not a package."""\n    spec = importlib.util.spec_from_file_location(\n        "sync_colors", ROOT / "tools" / "sync_colors.py")\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module\n\n\nSYNC = _sync()\n\n\ndef _colour_values():\n    """tests/colour_values.py, loaded by path, so this file is the same in every\n    application whichever way its tests import one another (#53 A)."""\n    spec = importlib.util.spec_from_file_location(\n        "colour_values_for_sync", pathlib.Path(__file__).with_name("colour_values.py"))\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module\n\n\nCV = _colour_values()\nMAPPING = SYNC.load_map(ROOT)\nCOLOURS = MAPPING["colours"]\nCOLOUR_FILE = MAPPING["colour_file"]\nMODULE = importlib.import_module(COLOUR_FILE[:-3].replace("/", "."))\n\n#: What each provenance class in the colour file means for the map. A class\n#: not listed here -- the mixer\'s "step", which covers register values and its\n#: own alike -- places no constraint.\nKINDS = {"register": "brand", "anchor": "brand",\n         "app-ramp": "own", "app-canvas": "own", "app-semantic": "own",\n         "derived": "code", "register-overlay": "code", "alias": "code"}\n\n\ndef _brand():\n    """The register as installed, refused unless it is the pinned commit."""\n    try:\n        brand, _ = SYNC.load_brand(ROOT)\n    except SYNC.SyncError as exc:\n        pytest.fail(str(exc))\n    return brand\n\n\ndef _text():\n    return SYNC.read(ROOT / COLOUR_FILE)[0]\n\n\n# ------------------------------------------------------------------ in sync\n\ndef test_the_colour_file_and_the_chart_are_what_the_sync_writes():\n    try:\n        plan = SYNC.build(ROOT)\n    except SYNC.SyncError as exc:\n        pytest.fail(str(exc))\n    stale = [path.relative_to(ROOT).as_posix()\n             for path, (before, after, _form) in plan.items() if before != after]\n    assert not stale, (\n        f"out of date: {\', \'.join(stale)}. Run: python tools/sync_colors.py\\n"\n        f"A value in {COLOUR_FILE} is written from brand_map.json and the brand "\n        f"at the pin; change the map, not the value.")\n\n\ndef test_every_colour_the_file_writes_is_in_the_map():\n    written = SYNC.colour_constants(_text())\n    missing = sorted(set(written) - set(COLOURS))\n    phantom = sorted(n for n in COLOURS if not hasattr(MODULE, n))\n    assert not missing, f"colours brand_map.json does not hold: {missing}"\n    assert not phantom, f"brand_map.json names what {COLOUR_FILE} does not have: {phantom}"\n    assert len(written) >= 20, f"only {len(written)} colours found -- the reader is blind"\n\n\ndef test_every_colour_the_app_owns_says_why():\n    owned = {n: e for n, e in COLOURS.items() if isinstance(e, dict)}\n    assert owned, "the map holds no colour of the application\'s own -- the reader is blind"\n    silent = [n for n, e in owned.items() if len(e.get("why", "").split()) < 3]\n    assert not silent, f"app-owned colours with no reason: {silent}"\n\n\ndef test_the_provenance_maps_agree_with_the_map():\n    """Each *PROVENANCE dict in the colour file classifies names. A register\n    value is a brand name in the map; an application\'s ramp step, canvas or\n    semantic colour is its own; a derived, overlay or alias value is code, and\n    not in the map."""\n    tables = [v for k, v in vars(MODULE).items()\n              if k.endswith("PROVENANCE") and isinstance(v, dict)]\n    assert tables, f"{COLOUR_FILE} has no provenance map -- the reader is blind"\n    wrong, read = [], 0\n    for table in tables:\n        for name, kind in table.items():\n            want = KINDS.get(kind)\n            entry = COLOURS.get(name)\n            if want is None:\n                continue\n            read += 1\n            if want == "brand" and not isinstance(entry, str):\n                wrong.append(f"{name} is {kind} and the map has {entry!r}")\n            elif want == "own" and not isinstance(entry, dict):\n                wrong.append(f"{name} is {kind} and the map has {entry!r}")\n            elif want == "code" and entry is not None:\n                wrong.append(f"{name} is {kind} and the map writes it as a value")\n    assert read >= 2, f"only {read} provenance entries read -- the reader is blind"\n    assert not wrong, "the provenance maps and brand_map.json disagree:\\n  " + "\\n  ".join(wrong)\n\n\n# ---------------------------------------------------------- the sync is looking\n\ndef _a_brand_line(text):\n    """A mapped brand colour written as a plain hex, and its line."""\n    for name, entry in COLOURS.items():\n        if not isinstance(entry, str):\n            continue\n        value = getattr(MODULE, name)\n        for line in text.split("\\n"):\n            if re.match(rf"{name}\\s*(:[^=]+)?=", line) and value in line:\n                return name, value, line\n    raise AssertionError("no brand colour written as a hex -- the reader is blind")\n\n\ndef test_the_sync_puts_back_a_value_edited_by_hand():\n    text = _text()\n    name, value, line = _a_brand_line(text)\n    other = CV.EXAMPLE_HAND_EDIT if value.lower() != CV.EXAMPLE_HAND_EDIT \\\n        else CV.EXAMPLE_HAND_EDIT_FALLBACK\n    edited = text.replace(line, line.replace(value, other), 1)\n    assert edited != text\n    assert SYNC.rewrite(edited, SYNC.resolve(MAPPING, _brand()), COLOUR_FILE) == text\n\n\ndef test_the_sync_refuses_a_colour_the_map_does_not_hold():\n    text = _text() + f\'\\nSTRAY_COLOUR: Final[str] = "{CV.EXAMPLE_HAND_EDIT}"\\n\'\n    with pytest.raises(SYNC.SyncError, match="STRAY_COLOUR"):\n        SYNC.rewrite(text, SYNC.resolve(MAPPING, _brand()), COLOUR_FILE)\n\n\ndef _a_derived_line(text):\n    """A colour the file works out in code, on one line with no comment."""\n    for line in text.split("\\n"):\n        match = re.match(r"([A-Z][A-Z0-9_]*)\\s*:[^=]+=\\s*(\\w+\\(.*\\)|[A-Z][A-Z0-9_]*)$", line)\n        if match and "#" not in line and match.group(1) not in COLOURS \\\n                and SYNC.is_colour(getattr(MODULE, match.group(1), None)):\n            return match.group(1)\n    raise AssertionError("no derived colour on a line of its own -- the reader is blind")\n\n\ndef test_the_sync_refuses_a_derived_colour_in_the_map():\n    name = _a_derived_line(_text())\n    resolved = dict(SYNC.resolve(MAPPING, _brand()))\n    resolved[name] = (getattr(MODULE, name), "app-owned")\n    with pytest.raises(SYNC.SyncError, match="code, not a value"):\n        SYNC.rewrite(_text(), resolved, COLOUR_FILE)\n\n\ndef test_the_sync_refuses_a_brand_that_is_not_the_pin(monkeypatch):\n    monkeypatch.setattr(SYNC, "installed_commit", lambda: "0" * 40)\n    with pytest.raises(SYNC.SyncError, match="pins"):\n        SYNC.load_brand(ROOT)\n\n\ndef test_a_brand_move_reaches_the_one_line_that_takes_it():\n    brand = _brand()\n    moved = types.SimpleNamespace(**{k: (dict(v) if isinstance(v, dict) else v)\n                                     for k, v in vars(brand).items() if not k.startswith("__")})\n    elsewhere = CV.EXAMPLE_MOVED_ACCENT if brand.APP["accent"].lower() != CV.EXAMPLE_MOVED_ACCENT \\\n        else CV.EXAMPLE_MOVED_ACCENT_FALLBACK\n    moved.APP["accent"] = elsewhere\n    text = _text()\n    after = SYNC.rewrite(text, SYNC.resolve(MAPPING, moved), COLOUR_FILE)\n    changed = [b for a, b in zip(text.split("\\n"), after.split("\\n")) if a != b]\n    assert len(changed) == 1 and changed[0].startswith("BRAND_GOLD") \\\n        and elsewhere in changed[0] and changed[0].endswith("# brand: APP.accent"), changed\n\n\n# ------------------------------------------------------------- the daily check\n\ndef test_the_daily_workflow_syncs_the_head_and_asks_only_when_a_colour_moved():\n    text = WORKFLOW.read_text(encoding="utf-8")\n    assert re.search(r"^\\s+schedule:\\s*$", text, re.M), "the workflow runs on no schedule"\n    assert "git ls-remote https://github.com/RNVizion/rnv-brand" in text, \\\n        "the workflow does not read the brand\'s head"\n    assert "python tools/sync_colors.py" in text, "the workflow does not run the sync"\n    assert f"git diff --quiet -- {COLOUR_FILE}" in text, \\\n        "the workflow does not ask whether the colour file moved"\n    assert "set -o pipefail" in text, "a sync that refuses would pass as nothing moved"\n    assert "gh pr create" in text and "gh pr view" in text, \\\n        "the workflow does not open, or look for, its pull request"\n', 'tools/sync_colors.py': '"""Write this application\'s colours from the brand.   RNV-COLOUR-SYNC, 2026-10-16\n\n    python tools/sync_colors.py           write the colour file and COLORS.md\n    python tools/sync_colors.py --check   write nothing; exit 1 if either is out of date\n\nbrand_map.json, at the repository root, says where each colour in the colour\nfile it names comes from: a name in rnv-brand, such as "APP.card", or a value\nthis application owns, with the reason. This script writes the value on each\nof those lines, and COLORS.md, the chart of this application\'s colours.\n\nTHE BRAND IS READ AT THE PIN. A brand name\'s value comes from rnv-brand as\ninstalled, and only when that is the commit pinned in\ntests/requirements-dev.txt, so what is written is what this repository\ndeclares, never whatever happens to be installed. Moving to a newer brand is:\nchange the pin, `pip install -r tests/requirements-dev.txt`, run this script,\nand read the diff of the colour file. It shows exactly what moved.\n.github/workflows/brand-sync.yml does that every day, and opens a pull\nrequest only when a colour this application uses has moved.\n\nNOTHING READS THE BRAND WHILE THE APPLICATION RUNS. The values are written\ninto the source and the build carries them. A derived colour, such as\nlighten(BRAND_GOLD, 13), stays code in the colour file and follows its base.\nImage files are not touched.\n\nTHE SAME FILE IN EVERY APPLICATION. What differs between them is in\nbrand_map.json: the colour file, the palettes the chart reads, and the map.\n\ntests/test_colours_in_sync.py runs the --check half of this on every run.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport ast\nimport importlib.metadata\nimport io\nimport json\nimport re\nimport sys\nimport tokenize\nfrom pathlib import Path\nfrom typing import Any\n\nROOT = Path(__file__).resolve().parent.parent\n\n#: Where this repository pins the register.\nDEV_REQS = "tests/requirements-dev.txt"\n\n#: The register\'s tables a map entry may name, as TABLE.key. A name with no\n#: table, such as GOLD_TEXT_GROUND_FLOOR, is one of the register\'s own\n#: constants.\nTABLES = ("PERMANENT", "APP", "STATUS")\n\n#: The same pin tests/test_register_pin.py reads: a full commit, never a branch.\nPIN_RE = re.compile(\n    r"^rnv-brand\\s*@\\s*git\\+https://github\\.com/RNVizion/rnv-brand"\n    r"(?:\\.git)?@(?P<ref>[0-9a-f]{40})\\s*$", re.M)\n\n#: One colour constant on one line, `NAME = <value>` or `NAME: <type> = <value>`,\n#: with the marker this script writes at the end, or none before its first run.\nLINE_RE = (r"^(?P<head>{name}(?:\\s*:[^=]+?)?\\s*=\\s*)(?P<value>.+?)"\n           r"(?P<mark>  # (?:brand: \\S+|app-owned))?$")\nMARK_RE = re.compile(r"  # (?:brand: \\S+|app-owned)$")\n\n_HEX_RE = re.compile(r"#[0-9a-fA-F]{6}(?:[0-9a-fA-F]{2})?")\n_RGBA_RE = re.compile(r"rgba?\\([\\d\\s,.]+\\)")\n_NAME_RE = re.compile(r"[A-Z][A-Z0-9_]*")\n\n\nclass SyncError(Exception):\n    """Something this script will not write past. The message says what to do."""\n\n\n# ------------------------------------------------------------------- files\n\ndef read(path: Path) -> tuple[str, tuple[bool, bool]]:\n    """A file as text with LF endings, and its form: (a byte-order mark, CRLF\n    throughout). An edit must not change the bytes it did not mean to."""\n    raw = path.read_bytes()\n    bom = raw.startswith(b"\\xef\\xbb\\xbf")\n    text = (raw[3:] if bom else raw).decode("utf-8")\n    crlf = text.count("\\r\\n")\n    all_crlf = crlf > 0 and crlf == text.count("\\n")\n    return (text.replace("\\r\\n", "\\n") if all_crlf else text), (bom, all_crlf)\n\n\ndef write(path: Path, text: str, form: tuple[bool, bool] = (False, False)) -> None:\n    bom, all_crlf = form\n    if all_crlf:\n        text = text.replace("\\n", "\\r\\n")\n    path.write_bytes((b"\\xef\\xbb\\xbf" if bom else b"") + text.encode("utf-8"))\n\n\n# ------------------------------------------------------------------ the map\n\ndef load_map(root: Path = ROOT) -> dict[str, Any]:\n    """brand_map.json, checked entry by entry before anything is written."""\n    data = json.loads((root / "brand_map.json").read_text(encoding="utf-8"))\n    colours = data.get("colours")\n    if not isinstance(colours, dict) or not colours:\n        raise SyncError("brand_map.json has no colours")\n    if not isinstance(data.get("colour_file"), str):\n        raise SyncError("brand_map.json does not name its colour_file")\n    for name, entry in colours.items():\n        if isinstance(entry, str):\n            table, dot, key = entry.partition(".")\n            if dot and (table not in TABLES or not key):\n                raise SyncError(f"{name}: {entry!r} is not TABLE.key, with TABLE "\n                                f"one of {\', \'.join(TABLES)}")\n            if not dot and not _NAME_RE.fullmatch(entry):\n                raise SyncError(f"{name}: {entry!r} is neither TABLE.key nor one of "\n                                f"the register\'s constants")\n        elif isinstance(entry, dict):\n            if set(entry) != {"app", "why"}:\n                raise SyncError(f"{name}: an app-owned colour is "\n                                f\'{{"app": <value>, "why": <reason>}}\')\n            if not isinstance(entry["why"], str) or not entry["why"].strip():\n                raise SyncError(f"{name}: an app-owned colour needs its reason")\n            if not is_colour(_as_python(entry["app"])):\n                raise SyncError(f"{name}: {entry[\'app\']!r} is not a colour")\n        else:\n            raise SyncError(f"{name}: an entry is a brand name or an app-owned object")\n    return data\n\n\ndef _as_python(value: Any) -> Any:\n    """A map value as Python holds it: JSON has no tuples."""\n    return tuple(value) if isinstance(value, list) else value\n\n\ndef is_colour(value: Any) -> bool:\n    """A hex, an rgb()/rgba() string, or an (r, g, b[, a]) tuple of bytes."""\n    if isinstance(value, str):\n        return bool(_HEX_RE.fullmatch(value) or _RGBA_RE.fullmatch(value))\n    if isinstance(value, tuple):\n        return len(value) in (3, 4) and all(\n            isinstance(c, int) and not isinstance(c, bool) and 0 <= c <= 255\n            for c in value)\n    return False\n\n\n# ---------------------------------------------------------------- the brand\n\ndef pinned_commit(root: Path = ROOT) -> str:\n    """The rnv-brand commit tests/requirements-dev.txt pins."""\n    match = PIN_RE.search((root / DEV_REQS).read_text(encoding="utf-8"))\n    if not match:\n        raise SyncError(f"{DEV_REQS} does not pin rnv-brand to a full commit")\n    return match.group("ref")\n\n\ndef installed_commit() -> str | None:\n    """The commit pip recorded when it installed rnv-brand, if it did."""\n    try:\n        dist = importlib.metadata.distribution("rnv-brand")\n    except importlib.metadata.PackageNotFoundError:\n        return None\n    raw = dist.read_text("direct_url.json")\n    if not raw:\n        return None\n    return json.loads(raw).get("vcs_info", {}).get("commit_id")\n\n\ndef load_brand(root: Path = ROOT) -> tuple[Any, str]:\n    """engine.brand, refused unless it is the pinned commit."""\n    pin = pinned_commit(root)\n    have = installed_commit()\n    if have != pin:\n        raise SyncError(\n            f"the rnv-brand installed here is "\n            f"{have[:7] if have else \'not one pip recorded a commit for\'}, and "\n            f"this repository pins {pin[:7]}. "\n            f"Run: pip install -r {DEV_REQS}")\n    import engine.brand as brand\n    return brand, pin\n\n\ndef brand_value(brand: Any, ref: str) -> str:\n    """The value a brand name holds in the register, in lower case."""\n    table, dot, key = ref.partition(".")\n    if dot:\n        values = getattr(brand, table, None)\n        if not isinstance(values, dict) or key not in values:\n            raise SyncError(f"rnv-brand has no {ref}")\n        value = values[key]\n    else:\n        if not hasattr(brand, ref):\n            raise SyncError(f"rnv-brand has no {ref}")\n        value = getattr(brand, ref)\n    if not (isinstance(value, str) and re.fullmatch(r"#[0-9a-fA-F]{6}", value)):\n        raise SyncError(f"{ref} is {value!r}, not a six-digit hex colour")\n    return value.lower()\n\n\n# ----------------------------------------------------------- the colour file\n\ndef spell(value: Any, like: str = \'"\') -> str:\n    """A value as the colour file writes it, in the quotes the line already uses."""\n    if isinstance(value, str):\n        if like.startswith("\'") and "\'" not in value:\n            return f"\'{value}\'"\n        return json.dumps(value)\n    return "(" + ", ".join(str(c) for c in value) + ")"\n\n\ndef resolve(mapping: dict[str, Any], brand: Any) -> dict[str, tuple[Any, str]]:\n    """Each mapped name: (its value, the marker its line carries)."""\n    out: dict[str, tuple[Any, str]] = {}\n    for name, entry in mapping["colours"].items():\n        if isinstance(entry, str):\n            out[name] = (brand_value(brand, entry), f"brand: {entry}")\n        else:\n            out[name] = (_as_python(entry["app"]), "app-owned")\n    return out\n\n\ndef colour_constants(text: str) -> list[str]:\n    """Every module-level constant written as a colour literal."""\n    names = []\n    for node in ast.parse(text).body:\n        if not isinstance(node, (ast.Assign, ast.AnnAssign)) or node.value is None:\n            continue\n        target = node.targets[0] if isinstance(node, ast.Assign) else node.target\n        if not isinstance(target, ast.Name):\n            continue\n        try:\n            value = ast.literal_eval(node.value)\n        except ValueError:\n            continue\n        if is_colour(value):\n            names.append(target.id)\n    return names\n\n\ndef rewrite(text: str, resolved: dict[str, tuple[Any, str]], where: str) -> str:\n    """The colour file with every mapped line written from the map."""\n    lines = text.split("\\n")\n    for name, (value, mark) in resolved.items():\n        pattern = re.compile(LINE_RE.format(name=re.escape(name)))\n        hits = [i for i, line in enumerate(lines) if pattern.match(line)]\n        if len(hits) != 1:\n            raise SyncError(f"{where}: expected one line defining {name}, "\n                            f"found {len(hits)}")\n        match = pattern.match(lines[hits[0]])\n        tokens = tokenize.generate_tokens(io.StringIO(match.group("value")).readline)\n        if any(token.type == tokenize.COMMENT for token in tokens):\n            raise SyncError(\n                f"{where}: {name}\'s line carries a comment the sync would drop. "\n                f"Move it to the line above; the sync writes the line\'s marker.")\n        try:\n            ast.literal_eval(match.group("value"))\n        except (ValueError, SyntaxError):\n            raise SyncError(\n                f"{where}: {name} is written as {match.group(\'value\')!r}, which is "\n                f"code, not a value. A derived colour stays code; take {name} "\n                f"out of brand_map.json.") from None\n        lines[hits[0]] = (f"{match.group(\'head\')}{spell(value, match.group(\'value\'))}"\n                          f"  # {mark}")\n    new = "\\n".join(lines)\n    unmapped = [n for n in colour_constants(new) if n not in resolved]\n    if unmapped:\n        raise SyncError(\n            f"{where} writes colours brand_map.json does not hold: "\n            f"{\', \'.join(unmapped)}. Add each, as a brand name or as app-owned "\n            f"with its reason.")\n    return new\n\n\n# ------------------------------------------------------------------ the chart\n\ndef _shown(value: Any) -> str:\n    return value if isinstance(value, str) else "(" + ", ".join(map(str, value)) + ")"\n\n\ndef _cell(text: str) -> str:\n    return text.replace("|", "\\\\|")\n\n\ndef _module_namespace(text: str, path: Path, root: Path) -> dict[str, Any]:\n    """The colour file\'s names, as it defines them from this text."""\n    module = ".".join(path.relative_to(root).with_suffix("").parts)\n    namespace: dict[str, Any] = {"__file__": str(path), "__name__": module}\n    added = str(root) not in sys.path\n    if added:\n        sys.path.insert(0, str(root))\n    try:\n        exec(compile(text, str(path.relative_to(root)), "exec"), namespace)\n    finally:\n        if added:\n            sys.path.remove(str(root))\n    return namespace\n\n\ndef _palettes(text: str, mapping: dict[str, Any], root: Path) -> list[tuple[str, str, ast.Dict]]:\n    """(locator, label, dict display) for each palette the chart reads."""\n    wanted = mapping.get("palettes")\n    found = []\n    if wanted is None:\n        for node in ast.parse(text).body:\n            if (isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name)\n                    and isinstance(node.value, ast.Dict)\n                    and ast.unparse(node.annotation) == "Final[ThemeDict]"):\n                found.append((node.target.id, node.value))\n    else:\n        for entry in wanted:\n            source = (text if entry["file"] == mapping["colour_file"]\n                      else read(root / entry["file"])[0])\n            body = ast.parse(source).body\n            *owner, name = entry["dict"].split(".")\n            for part in owner:\n                body = next(n for n in body if isinstance(n, ast.ClassDef) and n.name == part).body\n            node = next(n for n in body if isinstance(n, (ast.Assign, ast.AnnAssign))\n                        and getattr(n.targets[0] if isinstance(n, ast.Assign) else n.target,\n                                    "id", None) == name)\n            found.append((entry["dict"], node.value))\n    out = []\n    for locator, node in found:\n        label = next((v.value for k, v in zip(node.keys, node.values)\n                      if isinstance(k, ast.Constant) and k.value == "name"\n                      and isinstance(v, ast.Constant)), locator.split(".")[-1].title())\n        out.append((locator, label, node))\n    return out\n\n\ndef chart(text: str, mapping: dict[str, Any], brand: Any, pin: str, root: Path = ROOT) -> str:\n    """COLORS.md: the brand\'s names, their values, and this application\'s names."""\n    colour_path = root / mapping["colour_file"]\n    namespace = _module_namespace(text, colour_path, root)\n    tree = ast.parse(text)\n    colours = mapping["colours"]\n\n    source: dict[str, str] = {}\n    for node in tree.body:\n        if not isinstance(node, (ast.Assign, ast.AnnAssign)) or node.value is None:\n            continue\n        target = node.targets[0] if isinstance(node, ast.Assign) else node.target\n        if isinstance(target, ast.Name) and is_colour(namespace.get(target.id)):\n            source[target.id] = ast.unparse(node.value)\n\n    # A derived colour is made from the colour names its expression reads.\n    derived = [n for n in source if n not in colours]\n    reads = {n: {x.id for x in ast.walk(ast.parse(source[n], mode="eval"))\n                 if isinstance(x, ast.Name) and x.id in source} for n in derived}\n\n    def roots(name: str, seen: frozenset[str] = frozenset()) -> set[str]:\n        if name in colours:\n            return {name}\n        out: set[str] = set()\n        for base in reads.get(name, ()):\n            if base not in seen:\n                out |= roots(base, seen | {name})\n        return out\n\n    made_from: dict[str, list[str]] = {n: [] for n in colours}\n    for name in derived:\n        for base in sorted(roots(name)):\n            made_from[base].append(name)\n\n    def made(name: str) -> str:\n        return "<br>".join(\n            f"`{d}` = `{_cell(source[d])}` → `{_shown(namespace[d])}`"\n            for d in made_from[name]) or "—"\n\n    def brand_order(item: tuple[str, Any]) -> tuple[int, int]:\n        table, dot, key = item[1].partition(".")\n        if not dot:\n            return len(TABLES), 0\n        keys = list(getattr(brand, table))\n        return TABLES.index(table), keys.index(key)\n\n    from_brand = sorted(((n, e) for n, e in colours.items() if isinstance(e, str)),\n                        key=brand_order)\n    own = [(n, e) for n, e in colours.items() if isinstance(e, dict)]\n    orphans = [n for n in derived if not roots(n)]\n\n    out = [\n        f"# Colours: {mapping.get(\'app\', \'this application\')}",\n        "",\n        f"Generated by `python tools/sync_colors.py` from `brand_map.json`, "\n        f"`{mapping[\'colour_file\']}` and rnv-brand at `{pin[:7]}`, the commit pinned in "\n        f"`{DEV_REQS}`. Don\'t edit it by hand: change the map and run "\n        f"the script. `tests/test_colours_in_sync.py` fails when this file is out of date.",\n        "",\n        f"{len(from_brand)} colours come from the brand and {len(own)} are the "\n        f"application\'s own. {len(derived)} more are worked out in "\n        f"`{mapping[\'colour_file\']}` from those, so they follow them.",\n        "",\n        "## From the brand",\n        "",\n        "| brand name | value | the app\'s name | made from it in the app |",\n        "|---|---|---|---|",\n    ]\n    for name, ref in from_brand:\n        out.append(f"| `{ref}` | `{_shown(namespace[name])}` | `{name}` | {made(name)} |")\n    out += [\n        "",\n        "## The application\'s own",\n        "",\n        "| the app\'s name | value | why | made from it in the app |",\n        "|---|---|---|---|",\n    ]\n    for name, entry in own:\n        out.append(f"| `{name}` | `{_shown(namespace[name])}` | {_cell(entry[\'why\'])} "\n                   f"| {made(name)} |")\n    if orphans:\n        out += ["", "Worked out from no colour above: "\n                + ", ".join(f"`{n}`" for n in orphans) + "."]\n\n    # Each palette\'s keys, in order: the expression it writes, or "as dark"\n    # where it takes the entry from a palette it spreads.\n    out += ["", "## What each palette key takes", ""]\n    palettes = _palettes(text, mapping, root)\n    entries: dict[str, dict[str, str]] = {}\n    labels: dict[str, str] = {}\n    for locator, label, node in palettes:\n        written: dict[str, str] = {}\n        for key, value in zip(node.keys, node.values):\n            if key is None:\n                spread = ast.unparse(value).split(".")[-1]\n                base = next(l for l in entries if l.split(".")[-1] == spread)\n                written.update({k: f"as {labels[base].lower()}" for k in entries[base]})\n            elif isinstance(key, ast.Constant) and key.value != "name":\n                written[key.value] = ast.unparse(value)\n        entries[locator] = written\n        labels[locator] = label\n    out.append("| key | " + " | ".join(labels[l] for l in entries) + " |")\n    out.append("|---|" + "---|" * len(entries))\n    keys: list[str] = []\n    for written in entries.values():\n        keys += [k for k in written if k not in keys]\n    for key in keys:\n        cells = []\n        for locator, written in entries.items():\n            expr = written.get(key)\n            if expr is None:\n                cells.append("—")\n                continue\n            if expr.startswith("as "):\n                cells.append(expr)\n                continue\n            try:\n                value = eval(expr, dict(namespace))\n            except Exception:\n                cells.append(f"`{_cell(expr)}`")\n                continue\n            if not isinstance(value, (str, tuple)) or not (is_colour(value) or isinstance(value, str)):\n                cells.append(f"`{_cell(expr)}`")\n            elif expr == repr(value):\n                cells.append(f"`{_shown(value)}`")\n            else:\n                cells.append(f"`{_cell(expr)}` `{_shown(value)}`")\n        out.append(f"| `{key}` | " + " | ".join(cells) + " |")\n    notes = mapping.get("notes") or []\n    if notes:\n        out += ["", "## Not in the map", ""] + [f"- {_cell(n)}" for n in notes]\n    out += ["", "Which widgets each key reaches is in the fleet chart, *RNV Colour Chart*.", ""]\n    return "\\n".join(out)\n\n\n# --------------------------------------------------------------------- run it\n\ndef build(root: Path = ROOT) -> dict[Path, tuple[str, str, tuple[bool, bool]]]:\n    """Each file this script owns: (what is there, what it would write, its form)."""\n    mapping = load_map(root)\n    brand, pin = load_brand(root)\n    colour_path = root / mapping["colour_file"]\n    before, form = read(colour_path)\n    after = rewrite(before, resolve(mapping, brand), mapping["colour_file"])\n    chart_path = root / "COLORS.md"\n    chart_before, chart_form = read(chart_path) if chart_path.exists() else ("", (False, False))\n    return {colour_path: (before, after, form),\n            chart_path: (chart_before, chart(after, mapping, brand, pin, root), chart_form)}\n\n\ndef moved(before: str, after: str) -> list[str]:\n    """What a write changed: each value that moved, and how many lines only\n    gained their marker."""\n    changes, marked = [], 0\n    for a, b in zip(before.split("\\n"), after.split("\\n")):\n        if a == b:\n            continue\n        old, new = MARK_RE.sub("", a), MARK_RE.sub("", b)\n        if old == new:\n            marked += 1\n            continue\n        name = re.split(r"\\s*[:=]", new, maxsplit=1)[0]\n        changes.append(f"  {name}: {re.split(r\' = \', old, maxsplit=1)[-1]} -> "\n                       f"{re.split(r\' = \', new, maxsplit=1)[-1]}")\n    if marked:\n        changes.append(f"  {marked} line(s) marked, no value moved")\n    return changes\n\n\ndef main(argv: list[str] | None = None) -> int:\n    parser = argparse.ArgumentParser(description=__doc__.split("\\n", 1)[0])\n    parser.add_argument("--check", action="store_true",\n                        help="write nothing; exit 1 if a file is out of date")\n    args = parser.parse_args(argv)\n    try:\n        plan = build()\n    except SyncError as exc:\n        print(f"sync_colors: {exc}", file=sys.stderr)\n        return 2\n    stale = [path for path, (before, after, _form) in plan.items() if before != after]\n    if args.check:\n        for path in stale:\n            print(f"out of date: {path.relative_to(ROOT).as_posix()}")\n        if stale:\n            print("Run: python tools/sync_colors.py")\n            return 1\n        print("in sync")\n        return 0\n    for path in stale:\n        before, after, form = plan[path]\n        write(path, after, form)\n        print(f"wrote {path.relative_to(ROOT).as_posix()}")\n        if path.suffix == ".py":\n            print("\\n".join(moved(before, after)))\n    if not stale:\n        print("in sync; nothing to write")\n    return 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'}

